import{c as r,Q as o,j as s,m as n}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"ABSD-基于架构的软件设计","description":"","frontmatter":{"title":"ABSD-基于架构的软件设计"},"headers":[],"relativePath":"综合知识/架构设计/架构设计方法/基于架构的软件设计.md","filePath":"综合知识/架构设计/架构设计方法/基于架构的软件设计.md","lastUpdated":null}'),a={name:"综合知识/架构设计/架构设计方法/基于架构的软件设计.md"};function e(d,t,l,g,i,p){return o(),s("div",null,[...t[0]||(t[0]=[n('<blockquote><p>ABSD 是架构设计的核心方法论，六个子过程和三基础是高频选择题考点。</p></blockquote><p>基于架构的软件开发方法</p><h3 id="absd-概述" tabindex="-1">ABSD 概述 <a class="header-anchor" href="#absd-概述" aria-label="Permalink to &quot;ABSD 概述&quot;">​</a></h3><p>ABSD方法是架构驱动，强调<strong>由业务、质量和功能需求的组合</strong>驱动架构设计。它强调采用视角和视图来描述软件架构，采用用例和质量属性场景来描述需求。进一步来说，用例描述的是功能需求，质量属性场景描述的是质量需求（或侧重于非功能需求）。</p><p>使用ABSD方法，设计活动可以从项目总体功能框架明确就开始，这意味着需求获取和分析还没有完成，就开始了软件设计。</p><p>ABSD方法有三个基础。第一个基础是功能的分解，使用已有的基于模块的内聚和耦合技术；第二个基础是通过选择架构风格来实现质量和业务需求；第三个基础是软件模板的使用，软件模板利用了一些软件系统的结构。</p><p>ABSD方法是<strong>递归的</strong>，且迭代的每一个步骤都是清晰定义的。因此，不管设计是否完成，架构总是清晰的，有助于降低架构设计的随意性。</p><hr><blockquote><p>ABSD 方法是由<strong>商业、质量和功能需求</strong>的组合驱动的，是一个<strong>自顶向下、递归细化</strong>的方法，直到能产生<strong>软件构件和类</strong>。</p></blockquote><p><strong>ABSD 方法的三个基础：</strong></p><ol><li>对系统进行<strong>功能分解</strong></li><li>采用<strong>架构风格</strong>实现质量属性与商业需求</li><li>采用<strong>软件模板</strong>设计软件结构</li></ol><blockquote><p>⚠️ &quot;强调由业务、质量和功能需求的组合驱动&quot; 本身<strong>不属于</strong>三个基础（而是方法驱动因素）。</p></blockquote><h3 id="absd-六个子过程-高频必记" tabindex="-1">ABSD 六个子过程（高频必记） <a class="header-anchor" href="#absd-六个子过程-高频必记" aria-label="Permalink to &quot;ABSD 六个子过程（高频必记）&quot;">​</a></h3><p>架构设计是在<strong>需求分析之后，概要设计之前</strong>，是为了解决需求分析和软件设计之间的鸿沟问题。基于架构的软件开发过程可分为下列六步：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517145011.png" alt="image.png"></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>架构需求 → 架构设计 → 架构文档化 → 架构复审 → 架构实现 → 架构演化</span></span></code></pre></div><table tabindex="0"><thead><tr><th>子过程</th><th>核心内容</th></tr></thead><tbody><tr><td><strong>1. 架构需求</strong></td><td>获取需求（质量目标 + 系统商业目标 + 开发人员商业目标）</td></tr><tr><td><strong>2. 架构设计</strong></td><td>设计方案</td></tr><tr><td><strong>3. 架构文档化</strong></td><td>输出<strong>架构规格说明书</strong> + <strong>测试架构需求的质量设计说明书</strong></td></tr><tr><td><strong>4. 架构复审</strong></td><td>标识潜在风险，及早发现缺陷和错误</td></tr><tr><td><strong>5. 架构实现</strong></td><td>编码实现（基于文档化后的架构说明书）</td></tr><tr><td><strong>6. 架构演化</strong></td><td>应对需求变化，需先进行<strong>需求变化归类</strong></td></tr></tbody></table><blockquote><p>⚠️ 标识构件的正确顺序：<strong>生成类图 → 对类进行分组 → 把类打包成构件</strong></p></blockquote><hr><p>架构需求：重在掌握<strong>标识构件</strong>的三步，如下左图。</p><p>架构设计：将需求阶段的标识构件映射成构件，进行分析，如下右图。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517145105.png" alt="image.png"></p><p>架构（体系结构）文档化：主要产出两种文档，</p><ul><li>即<strong>架构（体系结构）规格说明</strong>，</li><li>测试架构（体系结构)需求的<strong>质量设计说明书</strong>。</li></ul><p>文档是至关重要的，是所有人员通信的手段，关系开发的成败。</p><p>架构复审：<strong>由外部人员</strong>（独立于开发组织之外的人，如用户代表和领域专家等）参加的复审，复审架构是否满足需求，质量问题，构件划分合理性等。若复审不过，则返回架构设计阶段进行重新设计、文档化，再复审。</p><p>架构实现：用实体来显示出架构。实现构件，构件组装成系统，如下左图：</p><p>架构演化：对架构进行改变，按需求增删构件，使架构可复用，如下右图：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517145311.png" alt="image.png"></p><h3 id="架构-体系结构-文档化" tabindex="-1">架构（体系结构）文档化 <a class="header-anchor" href="#架构-体系结构-文档化" aria-label="Permalink to &quot;架构（体系结构）文档化&quot;">​</a></h3><p><strong>ABSD 中文档化核心输出：</strong></p><ol><li><strong>体系结构规格说明</strong></li><li><strong>测试架构需求的质量设计说明书</strong></li></ol><p><strong>文档化原则：</strong></p><ul><li>从使用者角度书写</li><li>随时保证文档最新</li><li>分发给相关人员</li><li>针对不同背景的人员书写方式不同</li></ul><h3 id="架构复审" tabindex="-1">架构复审 <a class="header-anchor" href="#架构复审" aria-label="Permalink to &quot;架构复审&quot;">​</a></h3><ul><li>目的：<strong>标识潜在风险</strong>，及早发现架构设计中的缺陷和错误</li><li>必须邀请：<strong>独立于系统开发的外部人员</strong>（领域专家）</li><li>复审过程由<strong>用户代表与领域专家</strong>决定架构是否满足需求</li></ul><h3 id="架构描述与需求对应" tabindex="-1">架构描述与需求对应 <a class="header-anchor" href="#架构描述与需求对应" aria-label="Permalink to &quot;架构描述与需求对应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>描述对象</th><th>使用工具</th></tr></thead><tbody><tr><td>架构</td><td><strong>视角与视图</strong></td></tr><tr><td>功能需求</td><td><strong>用例</strong></td></tr><tr><td>质量需求</td><td><strong>质量场景</strong></td></tr></tbody></table><h3 id="软件系统四大基本功能-三硬件构件" tabindex="-1">软件系统四大基本功能 + 三硬件构件 <a class="header-anchor" href="#软件系统四大基本功能-三硬件构件" aria-label="Permalink to &quot;软件系统四大基本功能 + 三硬件构件&quot;">​</a></h3><p><strong>四大基本功能（自上而下）：</strong></p><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>数据存储</strong></td><td>存储和检索数据</td></tr><tr><td><strong>数据访问逻辑</strong></td><td>处理访问数据的过程</td></tr><tr><td><strong>应用逻辑</strong></td><td>DFD/用例/功能需求中记录的业务逻辑</td></tr><tr><td><strong>表示逻辑</strong></td><td>向用户显示信息并接收用户命令</td></tr></tbody></table><p><strong>三硬件构件：</strong> 客户端（Clients）、服务器（Servers）、网络（Network）</p>',42)])])}const b=r(a,[["render",e]]);export{c as __pageData,b as default};
